import { colorRoles, themes, type Theme } from './color.ts'
import {
  elevation,
  fontFamily,
  layout,
  motion,
  radius,
  space,
  textStyles,
  zIndex,
} from './scale.ts'

const header =
  '/* Generated by @cindl/tokens (pnpm --filter @cindl/tokens generate). Do not edit. */'
const rem = (px: number) => `${+(px / 16).toFixed(4)}rem`
const kebab = (value: string) => value.replace(/[A-Z]/g, (c) => `-${c.toLowerCase()}`)
const bezier = (points: readonly number[]) => `cubic-bezier(${points.join(', ')})`

function colorBlock(theme: Theme, shadows: { raised: string; overlay: string }) {
  return [
    ...colorRoles.map((role) => `  --color-${kebab(role)}: ${theme[role]};`),
    `  --shadow-raised: ${shadows.raised};`,
    `  --shadow-overlay: ${shadows.overlay};`,
  ]
}

/** CSS custom properties for web and the Electron renderer. */
export function renderTokensCss(): string {
  const scale = [
    ...Object.entries(space).map(
      ([k, v]) => `  --space-${k.replace('.', '_')}: ${rem(v)};`,
    ),
    ...Object.entries(radius).map(([k, v]) => `  --radius-${k}: ${v}px;`),
    `  --font-sans: '${fontFamily.sans}', ${fontFamily.sansFallback};`,
    `  --font-mono: '${fontFamily.mono}', ${fontFamily.monoFallback};`,
    ...Object.entries(textStyles).flatMap(([name, s]) => [
      `  --text-${name}-size: ${rem(s.size)};`,
      `  --text-${name}-line: ${rem(s.lineHeight)};`,
      `  --text-${name}-weight: ${s.weight};`,
      `  --text-${name}-tracking: ${s.tracking}em;`,
    ]),
    ...Object.entries(motion.duration).map(([k, v]) => `  --duration-${k}: ${v}ms;`),
    ...Object.entries(motion.easing).map(([k, v]) => `  --ease-${k}: ${bezier(v)};`),
    `  --spine-width: ${layout.spineWidth}px;`,
    `  --reading-measure: ${rem(layout.readingMeasure)};`,
    `  --margin-width: ${layout.marginWidth}px;`,
    // Never below the px floor; grows when the user enlarges text (rem).
    `  --touch-target: max(${layout.touchTarget}px, ${rem(layout.touchTarget)});`,
    `  --pointer-target: max(${layout.pointerTarget}px, ${rem(layout.pointerTarget)});`,
    ...Object.entries(zIndex).map(([k, v]) => `  --z-${k}: ${v};`),
  ]
  return [
    header,
    `/* Breakpoints (use literally in media queries): medium ${layout.breakpoints.medium}px, wide ${layout.breakpoints.wide}px. */`,
    ':root {',
    ...scale,
    '}',
    ":root,\n[data-theme='light'] {",
    '  color-scheme: light;',
    ...colorBlock(themes.light, elevation.light),
    '}',
    "[data-theme='dark'] {",
    '  color-scheme: dark;',
    ...colorBlock(themes.dark, elevation.dark),
    '}',
    '@media (prefers-color-scheme: dark) {',
    "  :root:not([data-theme='light']) {",
    '    color-scheme: dark;',
    ...colorBlock(themes.dark, elevation.dark).map((line) => `  ${line}`),
    '  }',
    '}',
    '@media (prefers-reduced-motion: reduce) {',
    '  :root {',
    ...Object.keys(motion.duration).map((k) => `    --duration-${k}: 0ms;`),
    '  }',
    '}',
    '',
  ].join('\n')
}

/** @font-face rules for the bundled, OFL-licensed faces. Paths are package-relative. */
export function renderFontsCss(): string {
  const face = (
    family: string,
    file: string,
    weight: string,
    style: 'normal' | 'italic',
    extra = '',
  ) =>
    [
      '@font-face {',
      `  font-family: '${family}';`,
      `  src: url('../fonts/${file}') format('woff2');`,
      `  font-weight: ${weight};`,
      `  font-style: ${style};`,
      extra,
      '  font-display: swap;',
      '}',
    ]
      .filter(Boolean)
      .join('\n')
  return [
    header,
    face(
      fontFamily.sans,
      'instrument-sans/InstrumentSans-Variable.woff2',
      '400 700',
      'normal',
      '  font-stretch: 75% 100%;',
    ),
    face(
      fontFamily.sans,
      'instrument-sans/InstrumentSans-Italic-Variable.woff2',
      '400 700',
      'italic',
      '  font-stretch: 75% 100%;',
    ),
    face(fontFamily.mono, 'jetbrains-mono/JetBrainsMono-Regular.woff2', '400', 'normal'),
    face(fontFamily.mono, 'jetbrains-mono/JetBrainsMono-Medium.woff2', '500', 'normal'),
    face(fontFamily.mono, 'jetbrains-mono/JetBrainsMono-Italic.woff2', '400', 'italic'),
    '',
  ].join('\n')
}
